import React, { useState, useEffect, useRef } from 'react';
import './SearchWidget.css';

const SearchWidget = ({ onClose, isVisible = true, initialQuery }) => {
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [searchContent, setSearchContent] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [searchHistory, setSearchHistory] = useState([]);

  // Widget State
  const [widgetPos, setWidgetPos] = useState({ x: window.innerWidth / 2 - 275, y: 100 });
  const [widgetSize, setWidgetSize] = useState({ width: 550, height: 600 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

  // Initialize history
  useEffect(() => {
    const savedHistory = localStorage.getItem('astra_search_history');
    if (savedHistory) {
      try {
        setSearchHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading search history:', e);
      }
    }
  }, []);

  // Handle incoming initialQuery
  useEffect(() => {
    if (initialQuery) {
      updateSearchContent(initialQuery);
    }
  }, [initialQuery]);

  // Dynamic Scaling Logic
  const applyDynamicScaling = () => {
    if (!widgetRef.current) return;

    const baseWidth = 550;
    const baseHeight = 600;
    const scaleX = widgetSize.width / baseWidth;
    const scaleY = widgetSize.height / baseHeight;
    const avgScale = (scaleX + scaleY) / 2;

    const textScale = Math.pow(avgScale, 0.7);
    const elementScale = Math.pow(avgScale, 0.8);
    const baseScale = Math.pow(avgScale, 0.6);

    const clampedTextScale = Math.max(0.6, Math.min(2.0, textScale));
    const clampedElementScale = Math.max(0.7, Math.min(2.2, elementScale));
    const clampedBaseScale = Math.max(0.5, Math.min(2.5, baseScale));

    widgetRef.current.style.setProperty('--text-scale', clampedTextScale);
    widgetRef.current.style.setProperty('--element-scale', clampedElementScale);
    widgetRef.current.style.setProperty('--base-scale', clampedBaseScale);
  };

  useEffect(() => {
    applyDynamicScaling();
  }, [widgetSize]);

  // Dragging Logic
  const handleDragStart = (e) => {
    // Prevent drag if clicking on controls, content text (to allow selection), or resize handles
    if (
      e.target.closest('.widget-controls') ||
      e.target.closest('.resize-handle') ||
      e.target.closest('button') ||
      e.target.closest('.search-content') || // Allow text selection
      e.target.closest('.search-history-item')
    ) return;

    setIsDragging(true);
    setDragOffset({
      x: e.clientX - widgetPos.x,
      y: e.clientY - widgetPos.y,
    });
  };

  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e) => {
      setWidgetPos({
        x: e.clientX - dragOffset.x,
        y: e.clientY - dragOffset.y,
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, dragOffset]);

  // Resizing Logic
  const handleResizeStart = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height,
    };
  };

  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (e) => {
      const deltaX = e.clientX - resizeStartRef.current.x;
      const deltaY = e.clientY - resizeStartRef.current.y;
      setWidgetSize({
        width: Math.max(400, resizeStartRef.current.width + deltaX),
        height: Math.max(400, resizeStartRef.current.height + deltaY)
      });
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isResizing]);

  // Content Logic
  const switchTab = (tabName) => setActiveTab(tabName);

  const updateSearchContent = async (text) => {
    setIsLoading(true);
    setActiveTab('current');
    await new Promise(resolve => setTimeout(resolve, 600));
    setSearchContent(text);
    setIsLoading(false);

    const newHistoryItem = {
      id: Date.now(),
      query: text.substring(0, 40) + (text.length > 40 ? '...' : ''),
      result: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      fullDate: new Date().toLocaleString()
    };
    const updatedHistory = [newHistoryItem, ...searchHistory].slice(0, 50);
    setSearchHistory(updatedHistory);
    localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));
  };

  const clearHistory = () => {
    setSearchHistory([]);
    localStorage.removeItem('astra_search_history');
  };

  const copyToClipboard = async () => {
    try { await navigator.clipboard.writeText(searchContent); } catch (err) { console.error(err); }
  };

  const increaseWidgetSize = () => setWidgetSize(p => ({ width: p.width + 100, height: p.height + 100 }));
  const decreaseWidgetSize = () => setWidgetSize(p => ({ width: Math.max(400, p.width - 100), height: Math.max(400, p.height - 100) }));

  if (!isVisible) return null;

  return (
    <div
      ref={widgetRef}
      id="searchWidget"
      className={`enhanced-widget search-widget ${isDragging ? 'widget-dragging' : ''}`}
      style={{
        left: `${widgetPos.x}px`,
        top: `${widgetPos.y}px`,
        width: `${widgetSize.width}px`,
        height: `${widgetSize.height}px`,
        position: 'fixed'
      }}
      onMouseDown={handleDragStart}
    >
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>

      <div className="widget-controls">
        <div className="widget-control-btn" onClick={increaseWidgetSize} title="Make Bigger">⧨</div>
        <div className="widget-control-btn" onClick={decreaseWidgetSize} title="Make Smaller">⧩</div>
        <div className="widget-control-btn" onClick={onClose} title="Close">⧬</div>
      </div>

      <div className="resize-handle" onMouseDown={handleResizeStart}></div>

      <div className="search-wrapper">
        <div className="search-label">SEARCH</div>

        <div className="controls-section">
          <div className="search-tabs">
            <button
              className={`tab-button ${activeTab === 'current' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('current'); }}
            >
              Current
            </button>
            <button
              className={`tab-button ${activeTab === 'history' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('history'); }}
            >
              History
            </button>
          </div>
        </div>

        <div className="search-screen-area">
          {activeTab === 'current' ? (
            <>
              {searchContent && !isLoading && <div className="search-result-label">SEARCH RESULT</div>}
              <div className="search-current-view">
                {isLoading ? (
                  <div className="search-loading show">
                    <div className="loading-spinner"></div>
                    <div>Searching for information...</div>
                  </div>
                ) : searchContent ? (
                  <div className="search-content">
                    {searchContent.split('\n').map((line, i) => (
                      <p key={i} style={{ marginBottom: '10px' }}>{line}</p>
                    ))}
                  </div>
                ) : (
                  <div className="search-placeholder">Ready to search.</div>
                )}
              </div>
              {!isLoading && searchContent && (
                <button className="copy-button" onClick={copyToClipboard} title="Copy to clipboard">
                  <i className="fas fa-copy"></i>
                </button>
              )}
            </>
          ) : (
            <div className="search-history-view">
              {searchHistory.length > 0 ? (
                <>
                  <div style={{ textAlign: 'right', marginBottom: '10px' }}>
                    <span onClick={clearHistory} style={{ fontSize: '10px', color: 'rgba(255,100,100,0.8)', cursor: 'pointer', textDecoration: 'underline' }}>CLEAR HISTORY</span>
                  </div>
                  {searchHistory.map(item => (
                    <div key={item.id} className="search-history-item" onClick={() => { setSearchContent(item.result); setActiveTab('current'); }}>
                      <div className="search-history-query">{item.query}</div>
                      <div className="search-history-date">{item.fullDate}</div>
                      <div className="search-history-preview">{item.result.substring(0, 80)}...</div>
                    </div>
                  ))}
                </>
              ) : (
                <div className="search-history-empty">No search history yet.</div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SearchWidget;
